import hashlib, json, struct

def sha256(b): return hashlib.sha256(b).hexdigest()

def cbor_encode_str(s):
    b=s.encode()
    l=len(b)
    if l < 24:
        return bytes([0x60 + l]) + b
    elif l < 256:
        return bytes([0x78, l]) + b
    elif l < 65536:
        return struct.pack(">BH", 0x79, l) + b
    else:
        return struct.pack(">BI", 0x7a, l) + b

def cbor_encode_array(arr):
    # arr is list of strings
    out=bytes([0x80 + len(arr)])
    for s in arr:
        out+=cbor_encode_str(s)
    return out

def cbor_encode_map(d):
    # d is dict str->str
    out=bytes([0xa0 + len(d)])
    for k,v in sorted(d.items()):
        out+=cbor_encode_str(k)
        out+=cbor_encode_str(v)
    return out

def bincode_str_varint(s):
    b=s.encode()
    # LEB128 unsigned for length
    n=len(b)
    out=bytearray()
    while True:
        byte = n & 0x7F
        n >>= 7
        if n:
            out.append(byte | 0x80)
        else:
            out.append(byte)
            break
    return bytes(out) + b

def bincode_str_fixed(s, fmt="<Q"):
    b=s.encode()
    return struct.pack(fmt, len(b)) + b

templates = []

# Simple concatenations
for sep in ["\n", "\x00", "|", ":", " ", "", "\x1f", "\x1e", "\n\n", "||", "::"]:
    templates.append((f"sep:{repr(sep)}", lambda q,a,sep=sep: (q+sep+a).encode()))

# With prefixes
for pre in ["", "basic:", "Basic:", "card:"]:
    for sep in ["\n", "\x00", "|"]:
        templates.append((f"pre:{pre} sep:{repr(sep)}", lambda q,a,pre=pre,sep=sep: (pre+q+sep+a).encode()))

# JSON
def json_basic(q,a, **kwargs):
    return json.dumps({"question":q,"answer":a}, **kwargs).encode()
for sort in [True, False]:
    for sep in [None, (',',':'), (', ',': ')]:
        templates.append((f"json sort={sort} sep={sep}", lambda q,a,sort=sort,sep=sep: json.dumps({"question":q,"answer":a}, sort_keys=sort, separators=sep if sep else None).encode()))

# JSON with type
for typ in ["Basic","basic"]:
    templates.append((f"json typ {typ}", lambda q,a,typ=typ: json.dumps({"type":typ,"question":q,"answer":a}, sort_keys=True).encode()))

# CBOR
templates.append(("cbor array", lambda q,a: cbor_encode_array([q,a])))
templates.append(("cbor map", lambda q,a: cbor_encode_map({"question":q,"answer":a})))
templates.append(("cbor map sorted", lambda q,a: cbor_encode_map({"answer":a,"question":q})))

# Bincode fixed
for fmt in ["<I","<Q",">I",">Q"]:
    templates.append((f"bincode fixed {fmt}", lambda q,a,fmt=fmt: bincode_str_fixed(q,fmt)+bincode_str_fixed(a,fmt)))

# Bincode varint
templates.append(("bincode varint", lambda q,a: bincode_str_varint(q)+bincode_str_varint(a)))

# Bincode with discriminant
for disc_fmt in ["<I","B"]:
    for disc_val in [0,1]:
        for fmt in ["<I","<Q"]:
            templates.append((f"bincode disc {disc_fmt} val {disc_val} fmt {fmt}", lambda q,a,disc_fmt=disc_fmt,disc_val=disc_val,fmt=fmt: (struct.pack(disc_fmt, disc_val) if disc_fmt!="B" else struct.pack("B",disc_val)) + bincode_str_fixed(q,fmt)+bincode_str_fixed(a,fmt)))

# Also try hashing question and answer individually then combined via struct
# e.g., hash of concatenated digests
# But that's not direct input, but we can test as separate step: template that returns digest concatenation then hash again? That would be double hash, but we can test as template that yields hex digest string
# For now, just test simple templates with sha256

found=[]
for name, fn in templates:
    ok=True
    for (q,a), target in hashes.items():
        try:
            inp=fn(q,a)
            h=hashlib.sha256(inp).hexdigest()
            if h != target:
                ok=False
                break
        except Exception as e:
            ok=False
            break
    if ok:
        print(f"FOUND template {name}")
        found.append(name)

if not found:
    print("no simple sha256 template found")

# Now try with other hash algos for each template that failed for sha256, try blake2b 32
for algo in ["blake2b", "sha512", "sha3_256", "shake_256"]:
    for name, fn in templates:
        ok=True
        for (q,a), target in hashes.items():
            try:
                inp=fn(q,a)
                if algo=="blake2b":
                    h=hashlib.blake2b(inp, digest_size=32).hexdigest()
                elif algo=="shake_256":
                    h=hashlib.shake_256(inp).hexdigest(32)
                else:
                    h=hashlib.new(algo, inp).hexdigest()
                    if len(h)>64:
                        h=h[:64]
                if h != target:
                    ok=False
                    break
            except:
                ok=False
                break
        if ok:
            print(f"FOUND algo {algo} template {name}")
            found.append((algo,name))
print("done search")
