# Since simple concatenations didn't match, maybe hashing includes normalization of markdown? But "a","b" are simple.
# Let's try to brute force with additional transformations: maybe they use `sha256` but input is `question` lowercased or trimmed plus answer? For "a","b" case doesn't matter.

# Could be they use `sha256` of `bincode` serialization of a Rust struct that includes `question` and `answer` as `String` but with `serde`'s `serialize` for `String` is just length+bytes, but we already tried bincode.

# Could be they use `sha256` of `postcard` or `ciborium`? Let's brute `ciborium` style: we tried cbor array and map, but cbor has multiple encodings for length (definite vs indefinite). Let's try different cbor variants.

import struct, hashlib, json

def cbor_str(s, major=3):
    b=s.encode()
    l=len(b)
    if l < 24:
        return bytes([major*32 + l]) + b if False else bytes([0x60 + l]) + b
    else:
        # Use 0x78 etc.
        if l < 256:
            return bytes([0x78, l]) + b
        elif l < 65536:
            return struct.pack(">BH", 0x79, l) + b
        else:
            return struct.pack(">BI", 0x7a, l) + b

# Let's brute all cbor encodings we can think: array of 2 strings, map of 2, etc.
pairs=[("a","b"),("Hello?","World")]
targets={}
for q,a in pairs:
    tmp=tempfile.mkdtemp()
    pathlib.Path(tmp,"Test.md").write_text(f"Q: {q}\nA: {a}\n")
    out=subprocess.check_output(["./executable","export",tmp],text=True)
    import json as j
    data=j.loads(out)
    targets[(q,a)]=data["cards"][0]["hash"]
    shutil.rmtree(tmp,ignore_errors=True)

def test_cbor_variants():
    variants=[]
    # Array [q,a]
    variants.append(("cbor array indefinite", lambda q,a: b"\x9f" + cbor_str(q)+cbor_str(a) + b"\xff"))
    variants.append(("cbor array definite 2", lambda q,a: bytes([0x82]) + cbor_str(q) + cbor_str(a)))
    # Map {question: q, answer: a} indefinite
    variants.append(("cbor map indefinite", lambda q,a: b"\xbf" + cbor_str("question")+cbor_str(q)+cbor_str("answer")+cbor_str(a)+b"\xff"))
    variants.append(("cbor map definite", lambda q,a: bytes([0xa2]) + cbor_str("answer")+cbor_str(a)+cbor_str("question")+cbor_str(q)))
    for name,fn in variants:
        ok=True
        for (q,a),targ in targets.items():
            h=hashlib.sha256(fn(q,a)).hexdigest()
            if h!=targ:
                ok=False
                break
        if ok:
            print("found",name)

test_cbor_variants()

# Let's also test postcard-like varint encoding: postcard uses varint for length (LEB128) but also for enum discriminant? We already tried varint for strings.

# Try with `bincode2` crate which uses varint for integers? Actually bincode2 uses fixed int encoding by default.

# Could be they use `bitcode` or `rmp_serde`? Let's try msgpack manually: msgpack for string "a" is 0xa1 0x61, for array 0x92...

def msgpack_str(s):
    b=s.encode()
    l=len(b)
    if l < 32:
        return bytes([0xa0 | l]) + b
    elif l < 256:
        return bytes([0xd9, l]) + b
    elif l < 65536:
        return struct.pack(">BH", 0xda, l) + b
    else:
        return struct.pack(">BI", 0xdb, l) + b

def msgpack_array(arr):
    # arr list of strings
    out=bytes([0x90 | len(arr)])
    for s in arr:
        out+=msgpack_str(s)
    return out

for name,fn in [("msgpack array", lambda q,a: msgpack_array([q,a]))]:
    ok=True
    for (q,a),targ in targets.items():
        h=hashlib.sha256(fn(q,a)).hexdigest()
        if h!=targ:
            ok=False
            break
    if ok:
        print("found msgpack",name)
    else:
        # print debug for first pair
        q,a = pairs[0]
        print(name, hashlib.sha256(fn(q,a)).hexdigest()[:12], "vs", targets[(q,a)][:12])

