                    data.extend_from_slice(&(a.len() as u64).to_le_bytes());
                    data.extend_from_slice(a.as_bytes());
                },
                _ => {}
            }
            if sha256_hex(&data)!=*targ { ok=false; break; }
        }
        if ok { println!("found len_fmt {}", len_fmt); return; }
    }
