def parse_md_file_inner(md_file, content, deck_name, collection_dir):
    lines = content.splitlines()
    n = len(lines)
    boundaries = []
    for idx, line in enumerate(lines):
        if line.startswith("Q:") or line.startswith("C:"):
            boundaries.append((line[0], idx))
    # Check for A: without Q
    for idx, line in enumerate(lines):
        if line.startswith("A:"):
            inside_q = False
            for b_idx, (b_type, start) in enumerate(boundaries):
                if b_type != "Q":
                    continue
                end_excl = boundaries[b_idx+1][1] if b_idx+1 < len(boundaries) else n
                if start <= idx < end_excl:
                    inside_q = True
                    break
            if not inside_q:
                eprint(f"hashcards: error: Parse error: Found answer tag without a question. Location: {md_file}:{idx+1}")
                sys.exit(1)
    # Check Q without answer
    for b_idx, (b_type, start) in enumerate(boundaries):
        if b_type != "Q":
            continue
        end_excl = boundaries[b_idx+1][1] if b_idx+1 < len(boundaries) else n
        segment = lines[start:end_excl]
        has_a = any(line.startswith("A:") for line in segment)
        if not has_a:
            if b_idx+1 < len(boundaries):
                eprint(f"hashcards: error: Parse error: New question without answer. Location: {md_file}:{boundaries[b_idx+1][1]+1}")
                sys.exit(1)
            else:
                eprint(f"hashcards: error: Parse error: File ended while reading a question without an answer. Location: {md_file}:{n+1}")
                sys.exit(1)
    cards = []
    for b_idx, (b_type, start) in enumerate(boundaries):
        end_excl = boundaries[b_idx+1][1] if b_idx+1 < len(boundaries) else n
        segment = lines[start:end_excl]
        line_start = start
        if b_idx+1 < len(boundaries):
            line_end = boundaries[b_idx+1][1]
        else:
            line_end = n-1 if n>0 else start
        deck = deck_name
        file_path_str = str(md_file.resolve())
        if b_type == "Q":
            a_idx = None
            for j, line in enumerate(segment):
                if line.startswith("A:"):
                    a_idx = j
                    break
            q_first = segment[0][2:]
            if q_first.startswith(" "):
                q_first = q_first.lstrip(" ")
            q_lines = [q_first]
            for k in range(1, a_idx):
                q_lines.append(segment[k])
            question = "\n".join(q_lines).strip()
            a_first = segment[a_idx][2:]
            if a_first.startswith(" "):
                a_first = a_first.lstrip(" ")
            a_lines = [a_first]
            for k in range(a_idx+1, len(segment)):
                a_lines.append(segment[k])
            answer = "\n".join(a_lines).strip()
            h = compute_basic_hash(question, answer, deck)
            cards.append({
                "hash": h,
                "familyHash": None,
                "deckName": deck,
                "location": {"filePath": file_path_str, "lineStart": line_start, "lineEnd": line_end},
                "content": {"basic": {"question": question, "answer": answer}},
            })
        else:
            c_first = segment[0][2:]
            if c_first.startswith(" "):
                c_first = c_first.lstrip(" ")
            c_lines = [c_first]
            for k in range(1, len(segment)):
                c_lines.append(segment[k])
            cloze_raw = "\n".join(c_lines).strip()
            if not re.search(r'\[([^\[\]]+)\]', cloze_raw):
                eprint(f"hashcards: error: Parse error: Cloze card must contain at least one cloze deletion. Location: {md_file}:{start+1}")
                sys.exit(1)
            matches = list(re.finditer(r'\[([^\[\]]+)\]', cloze_raw))
            de_text = ""
            last_end = 0
            deletions_info = []
            for m in matches:
                s, e = m.span()
                before = cloze_raw[last_end:s]
                de_text += before
                de_pos_byte = len(de_text.encode('utf-8'))
                inner = m.group(1)
                inner_byte_len = len(inner.encode('utf-8'))
                deletions_info.append((de_pos_byte, de_pos_byte + inner_byte_len - 1, inner))
                de_text += inner
                last_end = e
            de_text += cloze_raw[last_end:]
            family = compute_cloze_family(de_text)
            for (s,e, inner) in deletions_info:
                h = compute_cloze_card_hash(de_text, s, e, deck)
                cards.append({
                    "hash": h,
                    "familyHash": family,
                    "deckName": deck,
                    "location": {"filePath": file_path_str, "lineStart": line_start, "lineEnd": line_end},
                    "content": {"cloze": {"text": de_text, "start": s, "end": e}},
                })
    return cards

def get_collection_cards(collection_dir):
    p = pathlib.Path(collection_dir)
    if not p.exists() or not p.is_dir():
        eprint(f"hashcards: error: directory does not exist.")
        sys.exit(1)
    ensure_db(collection_dir)
    md_files = find_md_files(collection_dir)
    all_cards = []
    for md_file in md_files:
        try:
            content = md_file.read_text(encoding='utf-8')
        except Exception as e:
            eprint(f"hashcards: error: Failed to read {md_file}: {e}")
            sys.exit(1)
        deck_name = md_file.stem
        file_cards = parse_md_file_inner(md_file, content, deck_name, collection_dir)
        all_cards.extend(file_cards)
    return all_cards, []

def check_media_refs(collection_dir, cards):
    missing = []
    for card in cards:
        texts = []
        if 'basic' in card['content']:
            texts.append(card['content']['basic']['question'])
            texts.append(card['content']['basic']['answer'])
        else:
            texts.append(card['content']['cloze']['text'])
        for txt in texts:
            for m in re.finditer(r'!\[.*?\]\(.*?\)', txt):
                inner = m.group(0)
                try:
                    path = inner.split('](', 1)[1].rstrip(')')
                except:
                    continue
                if not path:
                    continue
                if path.startswith("@/"):
                    check_path = pathlib.Path(collection_dir) / path[2:]
                elif path.startswith("/"):
                    check_path = pathlib.Path(path)
                else:
                    card_dir = pathlib.Path(card['location']['filePath']).parent
                    check_path = card_dir / path
                if not check_path.exists():
                    missing.append((path, card['location']['filePath'], card['location']['lineStart']))
    # Deduplicate missing by path
    seen = set()
    uniq = []
    for path, fp, line in missing:
        if path not in seen:
            seen.add(path)
            uniq.append((path, fp, line))
    return uniq

